package com.openggf.game.soniccd;
import com.openggf.game.save.SaveManager;import com.openggf.game.session.SessionManager;import com.openggf.game.soniccd.objects.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.parallel.Isolated;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST. Strict original public continuation; no Frame/pool/clock hydration. */
@Isolated class TestCdOriginalR11TimeStarsWorld extends TestCdOriginalR11LoadingWorld {
 @Test void actualR11PowerupSourceIsTheExistingAuthenticatedNineScriptOwner()throws Exception{var a=TestCdOriginalBootPrefix.source().assets().openingObjects();var v=CdTimeStars.Assets.fromObjectAssets(a);assertEquals(a.view(com.openggf.game.soniccd.level.CdR11aObjectAssets.Table.POWERUP_MAPPINGS).range().nativeAddress(),v.mappingAddressBits());assertEquals(9,v.animations().scriptCount());assertSame(a.view(com.openggf.game.soniccd.level.CdR11aObjectAssets.Table.POWERUP_ANIMATIONS).bytes(),v.animations().bytes());}
 @Test void genuineEarlierObjectClearOwnsEveryReservedStarByte()throws Exception{try(var f=start()){var s=f.m.originalR11LoadingImage();assertTrue(s.clears().contains(CdLevelStartStorage.Cut.OBJECTS));for(int w=12;w<=15;w++)for(int at=0;at<64;at++)assertEquals(0,s.reserved().unsignedByte((w-1)*64+at));}}
 @Test void actualPublicCourseMustReturn4822AndReplayTheCreatedStars()throws Exception{try(var f=start()){for(int n=0;n<4821;n++)step(f.loop,input(n));var registry=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=registry.capture();var course=registry.captureCourse();step(f.loop,input(4821));assertFalse(f.m.originalR11EntryFrame().closed());assertTrue(f.m.originalR11EntryFrame().state().motion().routine()<6);var slots=f.m.originalR11LoadingImage().reserved();for(int w=12;w<=15;w++){int at=(w-1)*64;assertEquals(3,slots.unsignedByte(at));assertEquals(6,slots.unsignedByte(at+0x24));assertEquals(w-7,slots.unsignedByte(at+0x1C));}assertEquals(1,f.m.originalR11LoadingImage().globals().contact().timeWarp());var expected=image(f.m);for(boolean c:new boolean[]{false,true}){if(c)registry.restoreCourse(course);else registry.restore(full);step(f.loop,input(4821));CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.m));}}}
 @Test void actualStarBodiesMustReadCurrentHistoryAndReplayAfterInit()throws Exception{try(var f=start()){for(int n=0;n<4822;n++)step(f.loop,input(n));var r=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=r.capture();var course=r.captureCourse();step(f.loop,8);assertFalse(f.m.originalR11EntryFrame().closed());var expected=image(f.m);for(boolean c:new boolean[]{false,true}){if(c)r.restoreCourse(course);else r.restore(full);step(f.loop,8);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(f.m));}}}
 private Fixture start()throws Exception{var source=TestCdOriginalBootPrefix.source();var a=SonicCdGameModule.prepareSelectedProfile(source,new SaveManager(root),1,SonicCdGameModule.ProfileEntry.NEW_GAME,0);var m=a.module().orElseThrow();var b=boot();try{var loop=b.bootSonicCdSelectedProfile(source,a);for(int n=0;n<256&&m.originalR11LoadingPrefix().main().levelStartedByte()==0;n++)step(loop,0);assertEquals(1,m.originalR11LoadingPrefix().main().levelStartedByte());return new Fixture(b,loop,m);}catch(Exception|Error e){b.close();throw e;}}
 private record Fixture(com.openggf.tools.HeadlessGameBoot boot,com.openggf.GameLoop loop,SonicCdGameModule m)implements AutoCloseable{public void close(){try{SessionManager.clear();}finally{try{com.openggf.game.GameServices.graphics().cleanup();}finally{boot.close();}}}}
 private static int input(int n){return(n>=4000&&n<4032)||(n>=4096&&n<4128)||(n>=4608&&n<4640)?0x18:8;}
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingPrefix(),m.originalR11LoadingImage(),m.originalR11FirstLoad(),m.originalR11WorldImage(),m.selectedProfileState(),m.programServicesState());}
}
